// Read-only source comparison; generated files stay outside application data.
const fs=require('node:fs'),path=require('node:path');
const base='https://services4.arcgis.com/cjsiC6u2NZRyup0f/arcgis/rest/services/Great_Wall_of_China_WFL1/FeatureServer';
const out=path.resolve(__dirname,'../output/arcgis-great-wall');
const local=JSON.parse(fs.readFileSync(path.resolve(__dirname,'../data/great-wall/features.geojson'),'utf8')).features.filter(f=>f.geometry.type==='Point');
function distance(a,b){const rad=Math.PI/180,dlat=(b[1]-a[1])*rad,dlon=(b[0]-a[0])*rad;const h=Math.sin(dlat/2)**2+Math.cos(a[1]*rad)*Math.cos(b[1]*rad)*Math.sin(dlon/2)**2;return 6371008.8*2*Math.asin(Math.sqrt(Math.min(1,h)));}
function generic(name){return !name||/^(?:placemark|tower|fort|fort\s*[-+]\s*(?:tower|circular|square)|watchtower|beacon|[qhm]|\d+)$/i.test(name.trim());}
function meaningful(name){return !generic(name)&&!/^fort\b|^tower\b|^(?:small|tiny|large|possible|ruins|wall|watchtower|beacon)\b|^[?\s]+$|^[a-z]$|^(?:liao|jin|ming|han)\s*[#\d]/i.test(name||'');}
function nearest(feature,pool){let best=null,min=Infinity;for(const f of pool){const d=distance(feature.geometry.coordinates,f.geometry.coordinates);if(d<min){min=d;best=f;}}return best?{distanceMetres:Math.round(min),id:best.id,name:best.properties.name,category:best.properties.category,source:best.properties.source,originalPath:best.properties.originalPath}:null;}
async function get(url){const res=await fetch(url);if(!res.ok)throw Error(`HTTP ${res.status}`);const json=await res.json();if(json.error)throw Error(JSON.stringify(json.error));return json;}
async function download(id){if(process.argv.includes('--offline')){const name=id===0?'forts':'towers';return {meta:JSON.parse(fs.readFileSync(path.join(out,`${name}-metadata.json`))),features:JSON.parse(fs.readFileSync(path.join(out,`${name}.geojson`))).features};}const meta=await get(`${base}/${id}?f=json`),count=(await get(`${base}/${id}/query?where=1%3D1&returnCountOnly=true&f=json`)).count;
 const features=[];for(let offset=0;offset<count;offset+=1000){const params=new URLSearchParams({where:'1=1',outFields:'*',outSR:'4326',orderByFields:'OBJECTID ASC',resultOffset:String(offset),resultRecordCount:'1000',f:'json'});const page=await get(`${base}/${id}/query?${params}`);if(!page.features?.length)throw Error('Missing page');for(const f of page.features)features.push({type:'Feature',id:`arcgis-${id}-${f.attributes.OBJECTID}`,properties:f.attributes,geometry:{type:'Point',coordinates:[f.geometry.x,f.geometry.y]}});}
 if(features.length!==count||new Set(features.map(f=>f.id)).size!==count)throw Error('Incomplete or duplicate download');
 fs.writeFileSync(path.join(out,`${id===0?'forts':'towers'}.geojson`),JSON.stringify({type:'FeatureCollection',features}));fs.writeFileSync(path.join(out,`${id===0?'forts':'towers'}-metadata.json`),JSON.stringify(meta,null,2));return {meta,features};}
async function main(){fs.mkdirSync(out,{recursive:true});if(!process.argv.includes('--offline')){const item=await get('https://www.arcgis.com/sharing/rest/content/items/7858f29201864201802db840db2daf89?f=json');fs.writeFileSync(path.join(out,'service-item.json'),JSON.stringify(item,null,2));}const sets=await Promise.all([download(0),download(1)]);const rows=[],summary={comparedAt:new Date().toISOString(),source:base,localPointCount:local.length,layers:{}};
 for(let i=0;i<sets.length;i++){const {meta,features}=sets[i],compatible=local.filter(f=>(i===0?['fortress','city','town','guard','pass']:['tower','beacon']).includes(f.properties.category));const dynasty=meta.fields.find(f=>f.name==='Dynasty').domain.codedValues;const stats={total:features.length,meaningfulNames:0,byDynasty:{},decisions:{},distanceBuckets:{within100m:0,from100to300m:0,from300to1000m:0,beyond1000m:0}};
  for(const f of features){const p=f.properties,sameType=nearest(f,compatible),anyType=nearest(f,local),d=sameType?.distanceMetres??Infinity,any=anyType?.distanceMetres??Infinity;
   const decision=d<=100?'likely-duplicate':d<=300?'review-nearby':any<=100?'review-type-conflict':'candidate-new-location';const period=dynasty.find(v=>v.code===p.Dynasty)?.name||'Unknown';
   stats.byDynasty[period]=(stats.byDynasty[period]||0)+1;stats.decisions[decision]=(stats.decisions[decision]||0)+1;stats.distanceBuckets[d<=100?'within100m':d<=300?'from100to300m':d<=1000?'from300to1000m':'beyond1000m']++;if(meaningful(p.Name))stats.meaningfulNames++;
   rows.push({...f,properties:{...p,layer:meta.name,dynastyName:period,meaningfulName:meaningful(p.Name),decision,nearestCompatible:sameType,nearestAny:anyType}});
  }summary.layers[meta.name]=stats;
 }
 const pairs=[];for(let i=0;i<rows.length;i++)for(let j=i+1;j<rows.length;j++){const d=distance(rows[i].geometry.coordinates,rows[j].geometry.coordinates);if(d<=100){pairs.push({ids:[rows[i].id,rows[j].id],distanceMetres:Math.round(d),sameLayer:rows[i].properties.layer===rows[j].properties.layer,sameDynasty:rows[i].properties.Dynasty===rows[j].properties.Dynasty});for(const [a,b]of [[rows[i],rows[j]],[rows[j],rows[i]]]){a.properties.sourceNearbyIds||=[];a.properties.sourceNearbyIds.push(b.id);}}}summary.sourceNearbyPairsWithin100m=pairs;
 for(const decision of ['candidate-new-location','likely-duplicate','review-nearby','review-type-conflict'])fs.writeFileSync(path.join(out,`${decision}.geojson`),JSON.stringify({type:'FeatureCollection',features:rows.filter(f=>f.properties.decision===decision)}));
 fs.writeFileSync(path.join(out,'comparison.geojson'),JSON.stringify({type:'FeatureCollection',features:rows}));fs.writeFileSync(path.join(out,'summary.json'),JSON.stringify(summary,null,2));
 const report=['# ArcGIS 长城 Forts / Towers 比较','',`来源：${base}`,`对比本地 ${local.length} 个点。距离为 WGS84 球面距离；同类型范围为堡城/军堡/营城/卫所/关口及敌楼/烽燧。`,'','100米内同类型暂列重复，100–300米人工核查；100米内不同类型标为类型冲突；其余仅是新增位置候选，不是已验证遗址。英文与中文名称不强行互译，名称质量仅为启发式判断。','', '原始字段、坐标、朝代域值完整保留。Year 不直接用于建造年代。未接入应用。','', '```json',JSON.stringify(summary,null,2),'```','', '## 距已有点最远的非明候选（优先核查）','', '|图层|名称|原朝代|最近同类距离（米）|最近同类名称|','|---|---|---|---:|---|'];
 rows.filter(f=>f.properties.Dynasty!==6&&f.properties.decision==='candidate-new-location').sort((a,b)=>b.properties.nearestAny.distanceMetres-a.properties.nearestAny.distanceMetres).slice(0,25).forEach(f=>{const p=f.properties;report.push(`|${p.layer}|${String(p.Name).replace(/\|/g,'/')}|${p.dynastyName}|${p.nearestCompatible?.distanceMetres}|${p.nearestCompatible?.name}|`);});fs.writeFileSync(path.join(out,'comparison.md'),report.join('\n'));console.log(JSON.stringify(summary,null,2));
}
main().catch(e=>{console.error(e);process.exitCode=1;});
